import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Logo from "../assets/logos/logo_branca.png";  // Caminho da imagem do logo

const Login = () => {
  const [userDN, setUserDN] = useState("");  
  const [password, setPassword] = useState("");  
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const response = await fetch("http://localhost:5000/authenticate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userDN: `${userDN}@nutrihouse.intra`,  
          password,
        }),
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem("username", data.username);
        navigate("/home");
      } else {
        setError(data.message || "Falha na autenticação");
      }
    } catch (err) {
      setError("Erro ao conectar ao servidor");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="relative h-screen flex justify-center items-center bg-[#FAF9F7] px-4 overflow-hidden">
      {/* Fundo com as ondas */}
      <div className="absolute inset-0 z-[-1]">
        <div
          className="absolute top-0 left-0 w-full h-[30%] bg-cover bg-left"
          style={{ backgroundImage: "url('../assets/images/background_onda1.jpg')" }}
        ></div>
        <div
          className="absolute bottom-0 right-0 w-full h-[30%] bg-cover bg-right"
          style={{ backgroundImage: "url('../assets/images/background_onda2.jpg')" }}
        ></div>
      </div>

      {/* Box de Login */}
      <div className="login-box bg-gradient-to-b from-[#B95758] to-[#e14d3a] p-6 rounded-2xl shadow-lg text-center w-[380px] max-h-[80%] flex flex-col items-center">
        <img src={Logo} alt="Logo NutriHouse" className="w-[250px] mb-[-10px]" />

        <h2 className="text-white text-2xl font-bold mb-3">Bem-vindo</h2>
        <p className="text-white text-base mb-5">Faça seu login para continuar</p>

        {/* Formulário de login */}
        <form onSubmit={handleLogin} className="w-full flex flex-col gap-3">
          <div className="w-full">
            <label className="text-white font-bold text-left block mb-1">Usuário</label>
            <input
              type="text"
              id="usuario"
              value={userDN}
              onChange={(e) => setUserDN(e.target.value)}  // Atualizando o estado userDN
              placeholder="Digite seu usuário"
              className="w-full p-3 rounded-xl border-none outline-none"
              required
            />
          </div>
          
          <div className="w-full">
            <label className="text-white font-bold text-left block mb-1">Senha</label>
            <input
              type="password"
              id="senha"
              value={password}
              onChange={(e) => setPassword(e.target.value)}  // Atualizando o estado password
              placeholder="Digite sua senha"
              className="w-full p-3 rounded-xl border-none outline-none"
              required
            />
          </div>
          
          <button
            type="submit"
            disabled={loading}
            className="py-3 bg-white text-[#0c0b0b] font-bold rounded-full transition-all hover:bg-gray-100 mt-5 w-48 mx-auto"
          >
            {loading ? "Entrando..." : "Entrar"}
          </button>
        </form>

        {/* Recuperação de senha */}
        <a href="#" className="text-white text-sm mt-3 hover:underline">
          Esqueceu a senha?
        </a>

        {/* Exibindo erro caso ocorra */}
        {error && <p className="text-red-500 mt-3">{error}</p>}
      </div>
    </div>
  );
};

export default Login;
